using UnityEngine;

namespace VitalVR
{
    /// <summary>Optional gentle confirmation pulse and listening waveform; no sound is generated by default.</summary>
    public sealed class InteractionFeedback : MonoBehaviour
    {
        [SerializeField] private Transform[] waveBars;
        [SerializeField] private AudioSource audioSource;
        [SerializeField] private AudioClip softConfirmation;
        [SerializeField, Range(0f, 0.25f)] private float pulseAmount = 0.08f;

        private Vector3 baseScale;
        private float pulseUntil;
        private bool listening;

        private void Awake()
        {
            baseScale = transform.localScale;
        }

        private void Update()
        {
            float pulse = Time.unscaledTime < pulseUntil
                ? 1f + pulseAmount * Mathf.Sin((pulseUntil - Time.unscaledTime) * 24f)
                : 1f;
            transform.localScale = baseScale * pulse;

            if (waveBars == null) return;
            for (int i = 0; i < waveBars.Length; i++)
            {
                if (waveBars[i] == null) continue;
                Vector3 scale = waveBars[i].localScale;
                float wave = listening ? 0.35f + 0.65f * Mathf.Abs(Mathf.Sin(Time.unscaledTime * 4f + i * 0.65f)) : 0.12f;
                scale.y = wave;
                waveBars[i].localScale = scale;
            }
        }

        public void SetListening(bool value) { listening = value; }

        public void Pulse()
        {
            pulseUntil = Time.unscaledTime + 0.16f;
            if (audioSource != null && softConfirmation != null)
                audioSource.PlayOneShot(softConfirmation);
        }
    }
}
